        "viz_card_03_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Tracks Cisco SSE ZTNA connection statuses over time, enabling operators to follow adoption, detect access disruptions, and correlate denial spikes with policy or infrastructure changes\\."
            }
        },
